style.css:
@-moz-document domain("youtube.com") {
/* Main app background & shell */
    html, body, ytd-app, 
    #content, #page-manager, 
    ytd-watch-flexy, ytd-shorts {
        background-color: #FF0000 !important;
    }

    /* Video player container and background bars */
    #player-container, #player, .html5-video-player, 
    ytd-player, #container.ytd-player {
        background-color: #FF0000 !important;
    }

    /* Comments section and side panels */
    ytd-engagement-panel-section-list-renderer,
    #panels, ytd-comments, #sections,
    ytd-item-section-renderer,
    #comment-section {
        background-color: #FF0000 !important;
    }

    /* Top header bar & left navigation sidebar */
    #masthead, ytd-masthead, #guide, ytd-guide-renderer {
        background-color: #FF0000 !important;
    }

    /* Menus, dialogs, and popups */
    tp-yt-paper-dialog, ytd-menu-popup-renderer,
    .yt-spec-button-shape-next--filled {
        background-color: #FF0000 !important;
    }
}
